with t(k,bvi,ben,pmin,pmax,vmin,themes,tags,tone,kind) as (values
(0,'Phở nước dùng trong, bánh phở mềm, ăn kèm quẩy — bữa sáng quen thuộc của người Hà Nội.','Rice noodles in a clear, slow-cooked broth, with fried dough on the side — the classic Hanoi breakfast.',40,70,30,'{food}'::text[],'{localFood}'::text[],'butter','food'),(1,'Phở gà và bún thang — nước dùng gà thanh, bún thang nhiều topping thái sợi nhỏ.','Chicken pho and bún thang, a delicate Hanoi noodle soup topped with finely shredded egg, chicken and pork.',40,70,30,'{food}'::text[],'{localFood}'::text[],'butter','food'),(2,'Quán chay: món Việt nấu chay, nhiều lựa chọn cho người ăn chay.','Vegetarian place: Vietnamese dishes made plant-based.',50,150,45,'{food,rainy}'::text[],'{indoor}'::text[],'butter','food'),(3,'Bún chả: thịt nướng than hoa, nước chấm chua ngọt, bún và rau sống — món trưa kinh điển của Hà Nội.','Bún chả: charcoal-grilled pork in a sweet-and-sour dipping sauce with rice noodles and herbs — the classic Hanoi lunch.',50,80,35,'{food}'::text[],'{localFood,groups}'::text[],'butter','food'),(4,'Bún riêu cua: nước dùng cua đồng chua nhẹ vị cà chua, ăn kèm đậu rán và rau sống.','Bún riêu: rice noodles in a light tomato-and-crab broth with fried tofu and fresh herbs.',35,55,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(5,'Bún cá: cá rán giòn trong nước dùng chua nhẹ, thơm thì là.','Bún cá: crispy fried fish in a light, tangy broth with plenty of dill.',40,60,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(6,'Bún đậu mắm tôm: đậu rán, bún lá, rau thơm chấm mắm tôm — món dân dã, hợp đi nhóm (có thể xin nước mắm thay mắm tôm).','Bún đậu: fried tofu, pressed rice noodles and herbs with fermented shrimp paste — rustic and great for groups (ask for fish sauce if shrimp paste is too strong).',40,70,35,'{food}'::text[],'{localFood,groups}'::text[],'butter','food'),(7,'Bún mọc: nước dùng xương ngọt thanh, viên mọc thịt, sườn non.','Bún mọc: a gentle pork broth with pork meatballs and tender ribs.',35,55,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(8,'Bún ngan: thịt ngan (vịt xiêm) thái mỏng trong nước dùng măng.','Bún ngan: sliced muscovy duck in a broth with bamboo shoots.',40,60,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(9,'Bánh cuốn: bánh tráng mỏng hấp nóng, nhân thịt và mộc nhĩ, chấm nước mắm với chả.','Bánh cuốn: silky steamed rice rolls filled with pork and wood-ear mushroom, dipped in fish sauce.',35,55,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(10,'Bánh mì kẹp giòn nóng — bữa nhanh gọn để vừa ăn vừa đi.','A crispy Vietnamese baguette sandwich — a quick bite to eat on the go.',20,45,15,'{food}'::text[],'{localFood}'::text[],'butter','food'),(11,'Bánh mì chay — phiên bản thuần thực vật của món bánh mì Việt.','Vegan bánh mì — the Vietnamese sandwich, fully plant-based.',25,45,15,'{food}'::text[],'{localFood}'::text[],'butter','food'),(12,'Xôi nóng ăn kèm topping mặn — bữa sáng hay bữa phụ no lâu, giá dễ chịu.','Warm sticky rice with savoury toppings — a filling, cheap breakfast or snack.',20,45,15,'{food}'::text[],'{localFood}'::text[],'butter','food'),(13,'Miến lươn: lươn chiên giòn hoặc xào, ăn với miến nước hoặc miến trộn.','Miến lươn: glass noodles with crispy fried eel, in broth or tossed.',40,70,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(14,'Miến và bánh đa cua: nước dùng cua đồng, chả lá lốt, rau muống.','Crab noodle soup (miến or bánh đa) with field-crab broth and betel-leaf rolls.',40,70,25,'{food}'::text[],'{localFood}'::text[],'butter','food'),(15,'Chả cá: cá lăng tẩm nghệ, đảo với thì là và hành ngay tại bàn — đặc sản nổi tiếng của Hà Nội.','Chả cá: turmeric-marinated fish sizzled with dill and spring onion at your table — a famous Hanoi speciality.',150,250,50,'{food,rainy}'::text[],'{localFood,groups,indoor}'::text[],'butter','food'),(16,'Cháo lòng nóng, ăn kèm quẩy — món dân dã cho người thích thử món lạ.','Rice porridge with pork offal and fried dough — a rustic dish for adventurous eaters.',30,50,20,'{food}'::text[],'{localFood}'::text[],'butter','food'),(17,'Bánh xèo giòn, nem cuốn và quẩy — ăn vặt kiểu miền Trung và miền Nam ngay giữa phố cổ.','Crispy sizzling pancakes and fresh spring rolls — central and southern snacks in the Old Quarter.',40,80,30,'{food}'::text[],'{localFood,groups}'::text[],'butter','food'),(18,'Nem chua: thịt lên men chua nhẹ, ăn với tỏi ớt — món nhắm vặt quen thuộc.','Nem chua: tangy fermented pork with garlic and chilli — a classic snack.',25,60,15,'{food}'::text[],'{localFood}'::text[],'butter','food'),(19,'Nộm bò khô: đu đủ xanh, bò khô, lạc rang và nước chua ngọt — món ăn vặt bên phố.','Nộm: green papaya salad with dried beef, peanuts and a sweet-and-sour dressing — a street snack.',25,45,15,'{food}'::text[],'{localFood}'::text[],'butter','food'),(20,'Bánh chuối, bánh khoai, bánh tôm rán nóng giòn — món ăn vặt buổi chiều.','Hot, crispy banana, sweet-potato and shrimp fritters — an afternoon snack.',20,40,15,'{food}'::text[],'{localFood}'::text[],'butter','food'),(21,'Quán ốc: ốc luộc, ốc xào chấm nước gừng sả — vui nhất khi đi nhóm buổi tối.','Snail house: boiled and stir-fried snails with a ginger-lemongrass dip — most fun with friends in the evening.',60,150,45,'{food}'::text[],'{localFood,groups,lively}'::text[],'butter','food'),(22,'Bánh bao nhân thịt hấp nóng — ăn nhanh, rẻ.','Steamed pork buns — quick and cheap.',15,30,10,'{food}'::text[],'{localFood}'::text[],'butter','food'),(23,'Bánh gối rán nhân thịt, miến, mộc nhĩ, ăn với nước chấm và rau sống.','Bánh gối: pillow-shaped fried pastries filled with pork and glass noodles, served with dipping sauce.',25,50,20,'{food}'::text[],'{localFood}'::text[],'butter','food'),(24,'Cà phê trứng: lòng đỏ trứng đánh bông với đường, phủ lên cà phê đậm — thức uống đặc trưng của Hà Nội.','Egg coffee: egg yolk whipped with sugar over strong coffee — a Hanoi original.',35,60,30,'{food,rainy}'::text[],'{localFood,indoor}'::text[],'butter','food'),(25,'Quán cà phê để nghỉ chân: cà phê phin, cà phê sữa đá, đồ uống mát.','A café to rest your feet: drip coffee, iced milk coffee and cold drinks.',30,70,30,'{food,rainy}'::text[],'{indoor,quiet}'::text[],'butter','food'),(26,'Quán cà phê kiêm hiệu sách — chỗ ngồi yên tĩnh để đọc và nghỉ chân.','A café that doubles as a bookshop — a quiet place to read and rest.',35,70,40,'{food,rainy}'::text[],'{indoor,quiet}'::text[],'butter','food'),(27,'Kem que, kem ốc giá rẻ — món giải nhiệt quen thuộc của người Hà Nội.','Cheap, old-school ice cream — how Hanoians cool down.',10,30,10,'{food}'::text[],'{localFood,lively}'::text[],'butter','food'),(28,'Trà chanh vỉa hè: ngồi ghế nhựa, nhâm nhi trà và hạt hướng dương, ngắm phố.','Street-side lime tea on plastic stools — sip, crack sunflower seeds and watch the street.',15,30,20,'{food}'::text[],'{localFood,lively}'::text[],'butter','food'),(29,'Nhà hàng món Việt, hợp để ngồi ăn một bữa đầy đủ cùng gia đình hoặc nhóm bạn.','A Vietnamese restaurant for a proper sit-down meal with family or friends.',120,300,60,'{food,rainy}'::text[],'{groups,indoor}'::text[],'butter','food'),(30,'Rạp chiếu phim — lựa chọn cho buổi tối hoặc ngày mưa.','Cinema — a plan for the evening or a rainy day.',70,150,120,'{fun,rainy}'::text[],'{indoor,groups}'::text[],'teal','fun'),(31,'Bể bơi — bơi và giải nhiệt, hợp với gia đình có trẻ em.','Swimming pool — cool off; good for families with kids.',50,100,90,'{fun}'::text[],'{groups}'::text[],'teal','fun'),(32,'Khu nhảy bạt lò xo trong nhà — trẻ em và nhóm bạn đều thích.','Indoor trampoline park — loved by kids and groups of friends.',100,200,90,'{fun,rainy}'::text[],'{indoor,groups,lively}'::text[],'teal','fun'),(33,'Sân bóng đá mini cho thuê theo giờ — đá giao hữu với nhóm bạn.','A five-a-side pitch for hire by the hour — a kickabout with friends.',30,80,90,'{fun}'::text[],'{groups}'::text[],'teal','fun'),(34,'Sân vận động — vào xem khi có trận bóng đá.','Football stadium — catch a match when one is on.',50,150,120,'{fun}'::text[],'{groups,lively}'::text[],'teal','fun'),(35,'Sân trượt patin kèm quán cà phê.','A roller-skating rink with a café.',50,120,60,'{fun}'::text[],'{groups,lively}'::text[],'teal','fun'),(36,'Sân pickleball cho thuê theo giờ — môn thể thao đang rất thịnh ở Hà Nội.','Pickleball courts for hire — the sport everyone in Hanoi is playing right now.',50,150,60,'{fun}'::text[],'{groups}'::text[],'teal','fun'),(37,'Sản phẩm từ sữa bò Ba Vì như sữa chua, sữa tươi, bánh sữa — đặc sản của vùng đồi Ba Vì.','Ba Vì dairy — yoghurt, fresh milk and milk sweets from the hill farms, a local speciality.',20,80,20,'{food}'::text[],'{localFood}'::text[],'butter','food'),(38,'Nhà hàng chuyên các món thịt trâu.','A restaurant specialising in buffalo-meat dishes.',120,250,60,'{food}'::text[],'{groups,localFood}'::text[],'butter','food'),(39,'Nhà hàng ở vùng Ba Vì — chỗ nghỉ ăn trưa giữa hành trình.','A restaurant in the Ba Vì area — a lunch stop on the road.',100,250,60,'{food}'::text[],'{groups}'::text[],'butter','food'),(40,'Khu cắm trại trong rừng dưới chân núi Ba Vì — hợp đi nhóm và gia đình.','A forest campsite at the foot of Ba Vì mountain — good for groups and families.',50,200,180,'{fun,photo}'::text[],'{groups,photo}'::text[],'teal','fun'),(41,'Hồ nước rộng giữa vùng đồi Ba Vì — ngắm cảnh, chụp ảnh, dạo ven hồ.','A wide lake among the Ba Vì hills — views, photos and a lakeside stroll.',0,50,45,'{photo}'::text[],'{photo,quiet}'::text[],'leaf','sight'),(42,'Khu du lịch Ao Vua dưới chân núi Ba Vì: thác nước, hồ bơi và rừng cây — hợp đi gia đình ngày hè.','Ao Vua resort area at the foot of Ba Vì: a waterfall, pools and forest — good for a family summer day.',50,150,120,'{fun,photo}'::text[],'{groups,photo}'::text[],'teal','fun'),(43,'Đỉnh cao nhất dãy Ba Vì (1.296 m), trong Vườn quốc gia Ba Vì — ngày quang mây nhìn xuống cả vùng đồng bằng.','The highest peak of the Ba Vì range (1,296 m), inside Ba Vì National Park — on a clear day you see the whole plain below.',0,60,60,'{photo}'::text[],'{photo,iconic}'::text[],'leaf','sight'),(44,'Một trong ba đỉnh chính của dãy Ba Vì (1.131 m), đường lên có rừng thông và mây mù.','One of the three main peaks of the Ba Vì range (1,131 m), reached through pine forest and mist.',0,60,60,'{photo}'::text[],'{photo,quiet}'::text[],'leaf','sight'),(45,'Phế tích công trình thời Pháp thuộc trong rừng Vườn quốc gia Ba Vì — tường gạch phủ rêu, rễ cây ôm, góc chụp ảnh hoài cổ.','Ruins of a French-era building in the Ba Vì forest — moss-covered brick walls wrapped in tree roots, a moody photo spot.',0,0,30,'{photo,history}'::text[],'{photo,quiet}'::text[],'leaf','sight'),(46,'Khu trưng bày máy bay quân sự ngoài trời ở Sơn Tây, có tiêm kích MiG-21 và trực thăng Mi-8.','An open-air display of military aircraft in Sơn Tây, including a MiG-21 fighter and a Mi-8 helicopter.',0,0,20,'{history,photo}'::text[],'{free,photo}'::text[],'teal','sight')),
