insert into public.places (id,status,area,kind,depth,name_vi,name_en,lat,lng,address,opening_hours,themes,tags,visit_min,price_min_k,price_max_k,tone,blurb_vi,blurb_en,sources,review_notes)
select r.id,'approved',r.area,t.kind,'quick',r.name,r.name,r.lat,r.lng,r.addr,r.oh,t.themes,t.tags,t.vmin,t.pmin,t.pmax,t.tone,t.bvi,t.ben,'{openstreetmap}','Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.'
from r join t using (k)
on conflict (id) do update set status=excluded.status, area=excluded.area, kind=excluded.kind, depth=excluded.depth, name_vi=excluded.name_vi, name_en=excluded.name_en, opening_hours=excluded.opening_hours, themes=excluded.themes, tags=excluded.tags, visit_min=excluded.visit_min, price_min_k=excluded.price_min_k, price_max_k=excluded.price_max_k, tone=excluded.tone, blurb_vi=excluded.blurb_vi, blurb_en=excluded.blurb_en, review_notes=excluded.review_notes;
update public.places set kind='food' where id in ('bun-cha','egg-coffee');
select area, kind, depth, count(*) from public.places where status='approved' group by 1,2,3 order by 1,2,3;